CREATE COLUMN TABLE "TEST_AP"."OTAX" ("AbsEntry" INTEGER CS_INT NOT NULL , "SrcObjType" NVARCHAR(20) DEFAULT '-1' NOT NULL , "SrcObjAbs" INTEGER CS_INT DEFAULT -1 NOT NULL , "OrdinLNum" INTEGER CS_INT DEFAULT -1 NOT NULL , "Cancelled" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OTAX_SECONDARY" ON "TEST_AP"."OTAX" ( "SrcObjType" ASC, "SrcObjAbs" ASC, "OrdinLNum" ASC )